mapper.select:
SELECT t.* FROM ( SELECT tt.*, ifnull(round((ytbNum / tjNum)* 100, 2), 0) AS cy, ifnull(round((zbNum / ytbNum)* 100, 2), 0) AS zb FROM ( SELECT ssci.COMPANY_ID AS supId, ssci.COMPANY_NAME AS supName, ssci.COMPANY_CODE AS supCode, ssgcu.CONTACT_NAME AS contactName, ssgcu.CEEA_CONTACT_METHOD AS contactTel, ssgcu.EMAIL AS contactEmail, ssci.REGISTERED_CAPITAL AS registeredCapital, ssci.REGIST_CURRENCY AS bzCode, sma.AUTH_NUM AS zzLevel, ssci.COMPANY_CREATION_DATE AS comUp, round(DATEDIFF(CURDATE(), ssci.COMPANY_CREATION_DATE)/ 365, 2) AS comUpNum, IFNULL(ssci.APPLICATION_DATE, ssci.CREATION_DATE) AS regDate, ssci.COMPANY_ADDRESS AS address, sbr.AREA_NAME AS province, sbre.AREA_NAME AS city, tsso.num AS ytbNum, -- 已投标 数量 ssve.num AS tjNum, -- 推荐数量 sbnde.num AS zbNum, -- 中标数量 snpshe.num AS hgNum, -- 合同数量 snpshea.num AS bhgNum, -- 不中标数量 iih.PROJECT_NAME AS projectName, iih.PROJECT_NO AS projectCode, iih.CATEGORY_NAME AS pl, iih.CATEGORY_ID AS categoryId FROM (select * from meicloud_usrm_cloud_biz_supplier.scc_sup_company_info ci where ci.COMPANY_CODE IS NOT NULL AND ci.COMPANY_CODE !='') ssci LEFT JOIN (SELECT COMPANY_ID, CONTACT_NAME, CEEA_CONTACT_METHOD, EMAIL FROM meicloud_usrm_cloud_biz_supplier.scc_sup_contact_info WHERE CEEA_DEFAULT_CONTACT = 'Y' GROUP BY COMPANY_ID) ssgcu ON ssgcu.COMPANY_ID = ssci.COMPANY_ID LEFT JOIN (SELECT GROUP_CONCAT(AUTH_NUM) AS AUTH_NUM, COMPANY_ID FROM meicloud_usrm_cloud_biz_supplier.ceea_sup_management_attach GROUP BY COMPANY_ID) sma ON sma.COMPANY_ID = ssci.COMPANY_ID LEFT JOIN meicloud_usrm_cloud_biz_base.scc_base_region sbr ON sbr.REGION_ID = ssci.COMPANY_PROVINCE LEFT JOIN meicloud_usrm_cloud_biz_base.scc_base_region sbre ON sbre.REGION_ID = ssci.COMPANY_CITY
LEFT JOIN ( select sspo.VENDOR_ID,count(sspo.VENDOR_ID) as num from( SELECT ssp.VENDOR_ID, ssp.PROJECT_ID FROM meicloud_usrm_cloud_biz_sou.ext_scc_sou_order sso join meicloud_usrm_cloud_biz_sou.scc_sou_order ssp on ssp.ORDER_ID = sso.ORDER_ID join meicloud_usrm_cloud_biz_sou.scc_sou_project sp on sp.CREATE_APPROVAL_STATUS='APPROVED' and sp.PROJECT_ID = ssp.PROJECT_ID where sso.ORDER_STATUS in ('SUBMISSION','CANCEL') GROUP BY ssp.VENDOR_ID, ssp.PROJECT_ID) sspo GROUP BY sspo.VENDOR_ID ) tsso ON tsso.VENDOR_ID = ssci.COMPANY_ID LEFT JOIN ( SELECT COUNT(*) AS num, ssv.VENDOR_ID AS VENDOR_ID FROM meicloud_usrm_cloud_biz_sou.scc_sou_vendor ssv join meicloud_usrm_cloud_biz_sou.scc_sou_project ssp on ssp.PROJECT_ID = ssv.PROJECT_ID and ssp.SOU_TYPE = 'recomm' and ssp.PROJECT_STATUS='APPROVED' where not exists( SELECT 1 FROM meicloud_usrm_cloud_biz_sou.scc_sou_vendor ssv1 join meicloud_usrm_cloud_biz_sou.scc_sou_recomm_vendor ssp1 on ssp1.PROJECT_ID = ssv1.PROJECT_ID where ssp1.RCOMMEND_TYPE = 'ADD' and ssp1.ORIGINAL_EXT_RECOMMEND_NO = ssp.SOU_NO and ssv1.VENDOR_ID = ssv.VENDOR_ID ) GROUP BY ssv.VENDOR_ID) ssve ON ssve.VENDOR_ID = ssci.COMPANY_ID LEFT JOIN ( SELECT COUNT(*) AS num, sbnd.vendor_id AS vendor_id FROM meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice_detail sbnd LEFT JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice sbn ON sbnd.bid_notice_id = sbn.bid_notice_id WHERE sbn.`status` = 'APPROVED' AND sbnd.is_win = 'Y' GROUP BY sbnd.vendor_id) sbnde ON sbnde.vendor_id = ssci.COMPANY_ID LEFT JOIN ( SELECT COUNT(*) AS num, snpsh.COMPANY_ID AS COMPANY_ID FROM meicloud_usrm_cloud_biz_performance.scc_npm_project_score_header snpsh WHERE snpsh.PERFORMANCE_TYPE = 'PROJECT' AND snpsh.LEVEL_NAME IN ('合格', '合格待改善') GROUP BY snpsh.COMPANY_ID) snpshe ON snpshe.COMPANY_ID = ssci.COMPANY_ID LEFT JOIN (SELECT COUNT(*) AS num, snpsh.COMPANY_ID AS COMPANY_ID FROM meicloud_usrm_cloud_biz_performance.scc_npm_project_score_header snpsh WHERE snpsh.PERFORMANCE_TYPE = 'PROJECT' AND snpsh.LEVEL_NAME = '不合格' GROUP BY snpsh.COMPANY_ID) snpshea ON snpshea.COMPANY_ID = ssci.COMPANY_ID LEFT JOIN (SELECT snsih.VENDOR_ID AS VENDOR_ID, snsii.PROJECT_NAME AS PROJECT_NAME, snsii.PROJECT_NO AS PROJECT_NO, snsii.CATEGORY_NAME AS CATEGORY_NAME,snsii.CATEGORY_ID AS CATEGORY_ID FROM meicloud_usrm_cloud_biz_sou.scc_npm_sou_invite_item snsii LEFT JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_invite_head snsih ON snsih.INVITE_HEAD_ID = snsii.INVITE_HEAD_ID
AND snsii.CATEGORY_ID = #{pa.categoryId}
) iih ON iih.VENDOR_ID = ssci.COMPANY_ID
AND iih.PROJECT_NAME LIKE CONCAT('%', #{pa.projectName,jdbcType=VARCHAR}, '%')
GROUP BY ssci.COMPANY_ID ) tt ) t
AND t.supName LIKE CONCAT('%', #{pa.supName,jdbcType=VARCHAR}, '%')
AND t.supCode LIKE CONCAT('%', #{pa.supCode,jdbcType=VARCHAR}, '%')
AND t.contactName LIKE CONCAT('%', #{pa.contactName,jdbcType=VARCHAR}, '%')
AND t.contactTel LIKE CONCAT('%', #{pa.contactTel,jdbcType=VARCHAR}, '%')
AND t.address LIKE CONCAT('%', #{pa.address,jdbcType=VARCHAR}, '%')
AND t.province LIKE CONCAT('%', #{pa.province,jdbcType=VARCHAR}, '%')
AND t.city LIKE CONCAT('%', #{pa.city,jdbcType=VARCHAR}, '%')
AND t.cy >= #{pa.cylStart,jdbcType=DECIMAL}
AND t.cy <= #{pa.cylEnd,jdbcType=DECIMAL}
AND t.projectName LIKE CONCAT('%', #{pa.projectName,jdbcType=VARCHAR}, '%')
AND t.zb >= #{pa.zblStart,jdbcType=DECIMAL}
AND t.zb <= #{pa.zblEnd,jdbcType=DECIMAL}
AND t.registeredCapital >= #{pa.zcFundStart}
AND t.registeredCapital <= #{pa.zcFundEnd}
AND t.contactEmail LIKE CONCAT('%', #{pa.contactEmail,jdbcType=VARCHAR}, '%')
AND t.comUp >= #{pa.clYearStart,jdbcType=VARCHAR}
AND t.comUp <= #{pa.clYearEnd,jdbcType=VARCHAR}
AND t.zzLevel REGEXP #{pa.zzLevel,jdbcType=VARCHAR}
AND t.projectCode LIKE CONCAT('%', #{pa.projectCode,jdbcType=VARCHAR}, '%')
AND t.categoryId =#{pa.categoryId}

SELECT t.* FROM ( SELECT tt.*, round((ytbNum / tjNum)*100, 2) AS cy, round((zbNum / ytbNum)*100, 2) AS zb FROM ( SELECT ssci.COMPANY_ID AS supId, ssci.COMPANY_NAME AS supName, ssci.COMPANY_CODE AS supCode, ssgcu.USERNAME AS contactName, ssgcu.PHONE AS contactTel, ssgcu.EMAIL AS contactEmail, ssci.REGISTERED_CAPITAL AS registeredCapital, ssci.REGIST_CURRENCY AS bzCode, ( SELECT GROUP_CONCAT(sma.AUTH_NUM) FROM meicloud_usrm_cloud_biz_supplier.ceea_sup_management_attach sma WHERE sma.COMPANY_ID = ssci.COMPANY_ID) AS zzLevel, ssci.COMPANY_CREATION_DATE AS comUp, round(DATEDIFF(CURDATE(), ssci.COMPANY_CREATION_DATE)/365, 2) AS comUpNum, ssci.APPLICATION_DATE AS regDate, ssci.COMPANY_ADDRESS AS address, (SELECT sbr.AREA_NAME FROM meicloud_usrm_cloud_biz_base.scc_base_region sbr WHERE sbr.REGION_ID = ssci.COMPANY_PROVINCE) AS province, (SELECT sbr.AREA_NAME FROM meicloud_usrm_cloud_biz_base.scc_base_region sbr WHERE sbr.REGION_ID = ssci.COMPANY_CITY) AS city, ( SELECT COUNT(*) FROM ( SELECT sso.VENDOR_ID, sso.PROJECT_ID, COUNT(*) FROM meicloud_usrm_cloud_biz_sou.scc_sou_order sso GROUP BY sso.VENDOR_ID, sso.PROJECT_ID) t WHERE t.VENDOR_ID = ssci.COMPANY_ID ) AS ytbNum, ( SELECT COUNT(*) FROM meicloud_usrm_cloud_biz_sou.scc_sou_vendor ssv WHERE ssv.VENDOR_ID = ssci.COMPANY_ID ) AS tjNum, ( SELECT COUNT(*) FROM meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice_detail sbnd LEFT JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice sbn ON sbnd.bid_notice_id = sbn.bid_notice_id WHERE sbn.`status` = 'APPROVED' AND sbnd.is_win = 'Y' AND sbnd.vendor_id = ssci.COMPANY_ID ) AS zbNum, ( SELECT COUNT(*) FROM meicloud_usrm_cloud_biz_performance.scc_npm_project_score_header snpsh WHERE snpsh.COMPANY_ID = ssci.COMPANY_ID AND snpsh.PERFORMANCE_TYPE = 'PROJECT' AND snpsh.LEVEL_NAME IN ('合格', '合格待改善')) AS hgNum, ( SELECT COUNT(*) FROM meicloud_usrm_cloud_biz_performance.scc_npm_project_score_header snpsh WHERE snpsh.COMPANY_ID = ssci.COMPANY_ID AND snpsh.PERFORMANCE_TYPE = 'PROJECT' AND snpsh.LEVEL_NAME = '不合格') AS bhgNum FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info ssci LEFT JOIN meicloud_usrm_cloud_biz_supplier.scc_sup_green_channel_user ssgcu ON ssgcu.COMPANY_ID = ssci.COMPANY_ID ) tt ) t
AND t.supName LIKE CONCAT('%', #{pa.supName,jdbcType=VARCHAR}, '%')
AND t.supCode LIKE CONCAT('%', #{pa.supCode,jdbcType=VARCHAR}, '%')
AND t.contactName LIKE CONCAT('%', #{pa.contactName,jdbcType=VARCHAR}, '%')
AND t.contactTel LIKE CONCAT('%', #{pa.contactTel,jdbcType=VARCHAR}, '%')
AND t.address LIKE CONCAT('%', #{pa.address,jdbcType=VARCHAR}, '%')
AND t.province LIKE CONCAT('%', #{pa.province,jdbcType=VARCHAR}, '%')
AND t.city LIKE CONCAT('%', #{pa.city,jdbcType=VARCHAR}, '%')
AND t.cy >= #{pa.cylStart,jdbcType=DECIMAL}
AND t.cy <= #{pa.cylEnd,jdbcType=DECIMAL}
AND t.zb >= #{pa.zblStart,jdbcType=DECIMAL}
AND t.zb <= #{pa.zblEnd,jdbcType=DECIMAL}
AND t.registeredCapital >= #{pa.zcFundStart}
AND t.registeredCapital <= #{pa.zcFundEnd}
AND t.contactEmail LIKE CONCAT('%', #{pa.contactEmail,jdbcType=VARCHAR}, '%')
AND t.comUp >= #{pa.clYearStart,jdbcType=VARCHAR}
AND t.comUp <= #{pa.clYearEnd,jdbcType=VARCHAR}
AND t.zzLevel LIKE CONCAT('%', #{pa.zzLevel,jdbcType=VARCHAR}, '%')
AND t.supId IN
#{item}
